// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        // We test that after initialize, changeFee equals the passed _changeFee exactly.
        // The mutant adds 1, so the fuzzer will find an input where they differ.
        bytes32 dummyRoot = bytes32(uint256(1));
        c.initialize(
            address(0),
            address(0x1),
            1,
            1,
            _changeFee,
            0,
            dummyRoot,
            false,
            false
        );
        assertEq(c.changeFee(), _changeFee);
    }
}

